3	/**
4	 * The single definition of the E.164 form of a telephone number. Shared by
5	 * {@link NormalizeOwnerTelephone} (which stores the E.164 value) and {@link RequireUniqueTelephone}
6	 * (which compares against it), so both apply the same rule and cannot drift apart.
7	 *
8	 * <p>The rule: strip spaces, dashes and brackets. When a leading {@code '+'} is present, keep it and
9	 * the country code that follows; otherwise assume country code {@code '+61'} and drop a single leading
10	 * {@code '0'} from the national digits. The result must carry 8 to 15 digits after the {@code '+'};
11	 * anything else cannot form valid E.164 and yields {@code null}.
12	 *
13	 * <p>Kept out of the function classes themselves because OfficeFloor requires each function class to
14	 * expose exactly one public method.
15	 */
16	final class TelephoneNormalizer {
17	
18	    /**
19	     * Returns the E.164 form of the given telephone, or {@code null} when it cannot form a valid one.
20	     */
21	    static String toE164(String telephone) {
22	        if (telephone == null) {
23	            return null;
24	        }
25	        // Strip spaces, dashes and brackets.
26	        String cleaned = telephone.replaceAll("[\\s()-]", "");
27	        String digits;
28	        if (cleaned.startsWith("+")) {
29	            // Explicit country code: keep the digits that follow the '+'.
30	            digits = cleaned.substring(1);
31	        }
32	        else {
33	            // No country code: assume +61 and drop a single leading '0' from the national digits.
34	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
35	            digits = "61" + national;
36	        }
37	        // Everything after the '+' must be 8 to 15 digits.
38	        if (!digits.matches("\\d{8,15}")) {
39	            return null;
40	        }
41	        return "+" + digits;
42	    }
43	
44	    private TelephoneNormalizer() {
45	    }
46	}
